var t=`0290-kacamak`;var n=`world-0290`;var a=`ME`;var r=`southern-europe`;var s=4;var o=31;var l={en:`Kačamak`,ua:`Качамак`};var m={en:`A traditional Montenegro dish made with cornmeal, farmer cheese, sour cream. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Чорногорія. Основні інгредієнти: кукурудзяна крупа дрібного помелу, домашній кисломолочний сир, сметана. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`cornmeal`,300,`g`],[`water`,1e3,`ml`],[`table-salt`,4,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`unsalted-butter`,60,`g`],[`farmer-cheese`,250,`g`],[`sour-cream`,150,`g`]]}];var u={slug:t,id:n,country:`ME`,region:r,servings:4,minutes:31,title:l,text:m,steps:d};export{a as country,u as default,n as id,o as minutes,r as region,s as servings,t as slug,d as steps,m as text,l as title};